en_example:
package vcompare 1.0 1.1        ;# -1 (older)
package vcompare 2.0 2.0        ;#  0 (equal)
package vcompare 2.1 2.0.5      ;#  1 (newer)
package vcompare 1.2a3 1.2b1    ;# -1 (alpha before beta)

# Conditional based on Tcl version
if {[package vcompare [info patchlevel] 8.6] >= 0} {
    # We're on 8.6 or later
}

package require twapi

# Check whether plain text is on the clipboard
if {[twapi::clipboard_format_available 1]} {
    set text [twapi::read_clipboard 1]
    puts "Got [string length $text] characters of ANSI text"
}

package require twapi

# Modern preferred format
if {[twapi::clipboard_format_available 13]} {
    set text [twapi::read_clipboard 13]
    # Already a Tcl string -- emoji and CJK work
    puts $text
}

# Equivalent via Tk's built-in (cross-platform):
if {![catch {clipboard get -type STRING} text]} {
    puts $text
}

```tcl
# Uppercase every word
regsub -all -command {\w+} "hello world" {apply {{s} {string toupper $s}}}
# => HELLO WORLD

# Hex-encode each codepoint > 127
regsub -all -command {[^\x00-\x7f]} "Café" {apply {{c} {
    format "\\u%04X" [scan $c %c]
}}}
# => Caf\u00E9

package require twapi

# Find all Notepad windows and bring one to front
set hwnds [twapi::find_windows -text "*Notepad*" -visible 1]
foreach hwnd $hwnds {
    puts "Window $hwnd: [twapi::get_window_text $hwnd]"
}
if {[llength $hwnds] > 0} {
    twapi::set_foreground_window [lindex $hwnds 0]
}

# Get Tk's HWND for a toplevel (for native Win32 interop)
set hwnd [twapi::tkpath_to_hwnd .myToplevel]
